def new_item(topic, number, description):
    t = next(t for t in topics if t['id'] == f'topic-{topic:04d}')
    identity = ident(topic, number)
    assert identity not in items
    item = {'id': identity, 'description': description, 'relation_type': 'topic', 'verse_keys': []}
    t['items'].append(item)
    items[identity] = item
    notes[identity] = {}
    topic_changes.append({'topic_id': t['id'], 'field': 'items', 'added_item_id': identity, 'reason': 'Разделено самостоятельное содержание и характер основания связи: ' + description + '.'})
    return item

