t42['scope_note'] = 'Насх отдельных предписаний не означает утрату канонического статуса записанных аятов или их изъятие из Корана. Вопросы о пределах отмены и разногласия толкователей отмечены отдельно; спорные случаи не представлены как единогласные.'
topic_changes.append({'topic_id': t42['id'], 'field': 'scope_note', 'reason': t42['scope_note']})
